campo_HASH_do_qrcode_BU = "777EF9A01B133942791B416171DDE075BBB7C329738528DBDF06C3E0A8FD753543ADCDACB659606B34F8E16B8D6833D6F01B762908CD2BF98E89ECB9DB5C4C23"
